    43→
    44→export class BackupValidator {
    45→  private zipBuffer: Buffer;
    46→  private extractedFiles: Map<string, Record<string, unknown> | Buffer> =
    47→    new Map();
    48→  private metadata: BackupMetadata | null = null;
    49→
    50→  constructor(zipBuffer: Buffer) {
    51→    this.zipBuffer = zipBuffer;
    52→  }
    53→
    54→  async validate(): Promise<ValidationResult> {
    55→    const errors: string[] = [];
    56→    const warnings: string[] = [];
    57→    const conflicts: Conflict[] = [];
    58→
    59→    try {
    60→      // Extract and validate ZIP structure
    61→      await this.extractZipContents();
    62→
    63→      // Validate metadata
    64→      const metadataValidation = await this.validateMetadata();
    65→      if (!metadataValidation.isValid) {
    66→        errors.push(...metadataValidation.errors);
    67→        return this.createValidationResult(false, conflicts, errors, warnings);
    68→      }
    69→
    70→      // Validate data files
    71→      const dataValidation = await this.validateDataFiles();
    72→      if (!dataValidation.isValid) {
    73→        errors.push(...dataValidation.errors);
    74→        warnings.push(...dataValidation.warnings);
    75→      }
    76→
    77→      // Detect conflicts with existing data
    78→      const conflictDetection = await this.detectConflicts();
    79→      conflicts.push(...conflictDetection.conflicts);
    80→      warnings.push(...conflictDetection.warnings);
    81→
    82→      const isValid = errors.length === 0;
    83→      return this.createValidationResult(isValid, conflicts, errors, warnings);
    84→    } catch (error) {
    85→      console.error("Backup validation error:", error);
    86→      errors.push(
    87→        `Validation failed: ${error instanceof Error ? error.message : "Unknown error"}`
    88→      );
    89→      return this.createValidationResult(false, conflicts, errors, warnings);
    90→    }
    91→  }
    92→
    93→  private async extractZipContents(): Promise<void> {
    94→    return new Promise((resolve, reject) => {
    95→      const directory = unzipper.Open.buffer(this.zipBuffer);
    96→
    97→      directory
    98→        .then(async (dir) => {
    99→          for (const file of dir.files) {
   100→            if (file.type === "File") {
   101→              const content = await file.buffer();
   102→
   103→              if (file.path.endsWith(".json")) {
   104→                try {
   105→                  const jsonData = JSON.parse(content.toString());
   106→                  this.extractedFiles.set(file.path, jsonData);
   107→                } catch (error) {
   108→                  throw new Error(
   109→                    `Invalid JSON in file ${file.path}: ${error}`
   110→                  );
   111→                }
   112→              } else {
   113→                // Store binary files (photos) as buffers
   114→                this.extractedFiles.set(file.path, content);
   115→              }
   116→            }
   117→          }
   118→          resolve();
   119→        })
   120→        .catch(reject);
   121→    });
   122→  }
   123→
   124→  private async validateMetadata(): Promise<{
   125→    isValid: boolean;
   126→    errors: string[];
   127→  }> {
   128→    const errors: string[] = [];
   129→
   130→    if (!this.extractedFiles.has("metadata.json")) {
   131→      errors.push("Missing metadata.json file");
   132→      return { isValid: false, errors };
   133→    }
   134→
   135→    try {
   136→      const metadataData = this.extractedFiles.get("metadata.json");
   137→      this.metadata = backupMetadataSchema.parse(metadataData);
   138→
   139→      // Check version compatibility
   140→      if (!SUPPORTED_VERSIONS.includes(this.metadata.version)) {
   141→        errors.push(
   142→          `Unsupported backup version: ${this.metadata.version}. Supported versions: ${SUPPORTED_VERSIONS.join(", ")}`
   143→        );
   144→      }
   145→
   146→      // Validate required data files exist
   147→      for (const dataFile of this.metadata.dataFiles) {
   148→        if (!this.extractedFiles.has(dataFile)) {
   149→          errors.push(`Missing required data file: ${dataFile}`);
   150→        }
   151→      }
   152→
   153→      return { isValid: errors.length === 0, errors };
   154→    } catch (error) {
   155→      errors.push(
   156→        `Invalid metadata format: ${error instanceof Error ? error.message : "Unknown error"}`
   157→      );
   158→      return { isValid: false, errors };
   159→    }
   160→  }
   161→
   162→  private async validateDataFiles(): Promise<{
   163→    isValid: boolean;
   164→    errors: string[];
   165→    warnings: string[];
   166→  }> {
   167→    const errors: string[] = [];
   168→    const warnings: string[] = [];
   169→
   170→    if (!this.metadata) {
   171→      errors.push("Metadata not loaded");
   172→      return { isValid: false, errors, warnings };
   173→    }
   174→
   175→    // Validate people data
   176→    if (this.extractedFiles.has("data/people.json")) {
   177→      const peopleData = this.extractedFiles.get("data/people.json");
   178→      if (!Array.isArray(peopleData)) {
   179→        errors.push("People data must be an array");
   180→      } else {
   181→        for (let i = 0; i < peopleData.length; i++) {
   182→          try {
   183→            personDataSchema.parse(peopleData[i]);
   184→          } catch (error) {
