   186→              `Invalid person data at index ${i}: ${error instanceof Error ? error.message : "Unknown error"}`
   187→            );
   188→          }
   189→        }
   190→      }
   191→    }
   192→
   193→    // Validate users data
   194→    if (this.extractedFiles.has("data/users.json")) {
   195→      const usersData = this.extractedFiles.get("data/users.json");
   196→      if (!Array.isArray(usersData)) {
   197→        errors.push("Users data must be an array");
