   280→    // Check for relationship conflicts
   281→    if (this.extractedFiles.has("data/relationships.json")) {
   282→      const relationshipsData = this.extractedFiles.get(
   283→        "data/relationships.json"
   284→      );
   285→      if (Array.isArray(relationshipsData)) {
   286→        const relationshipConflicts = await this.detectRelationshipConflicts(
