   296→  private async detectPeopleConflicts(
   297→    peopleData: Record<string, unknown>[]
   298→  ): Promise<Conflict[]> {
   299→    const conflicts: Conflict[] = [];
   300→
   301→    for (const person of peopleData) {
   302→      // Check for ID conflicts
   303→      const personId = String(person.id || "");
   304→      const existingById = await db.person.findUnique({
   305→        where: { id: personId },
   306→      });
   307→
   308→      if (existingById) {
   309→        conflicts.push({
   310→          type: "person",
   311→          action: "update",
   312→          existingId: existingById.id,
   313→          existingData: existingById,
   314→          newData: person,
   315→          conflictFields: this.getChangedFields(existingById, person),
   316→          severity: "medium",
   317→          description: `Person with ID ${personId} already exists`,
   318→        });
   319→        continue;
   320→      }
   321→
   322→      // Check for email conflicts
   323→      const personEmail =
   324→        typeof person.email === "string" ? person.email : undefined;
   325→      if (personEmail) {
   326→        const existingByEmail = await db.person.findFirst({
   327→          where: { email: personEmail },
   328→        });
   329→
   330→        if (existingByEmail) {
   331→          conflicts.push({
   332→            type: "person",
   333→            action: "create",
   334→            existingId: existingByEmail.id,
   335→            existingData: existingByEmail,
   336→            newData: person,
   337→            conflictFields: ["email"],
   338→            severity: "high",
   339→            description: `Person with email ${personEmail} already exists`,
   340→          });
   341→        }
   342→      }
   343→
   344→      // Check for name conflicts (potential duplicates)
   345→      const personFirstName = String(person.firstName || "");
   346→      const personLastName = String(person.lastName || "");
   347→      const existingByName = await db.person.findFirst({
   348→        where: {
   349→          firstName: personFirstName,
   350→          lastName: personLastName,
   351→          dateOfBirth:
   352→            typeof person.dateOfBirth === "string"
   353→              ? new Date(person.dateOfBirth)
   354→              : undefined,
   355→        },
   356→      });
   357→
   358→      if (existingByName) {
   359→        conflicts.push({
   360→          type: "person",
   361→          action: "create",
   362→          existingId: existingByName.id,
   363→          existingData: existingByName,
   364→          newData: person,
   365→          conflictFields: ["firstName", "lastName", "dateOfBirth"],
   366→          severity: "low",
   367→          description: `Potential duplicate person: ${personFirstName} ${personLastName}`,
   368→        });
   369→      }
