   374→
   375→  private async detectUserConflicts(
   376→    usersData: Record<string, unknown>[]
   377→  ): Promise<Conflict[]> {
   378→    const conflicts: Conflict[] = [];
   379→
   380→    for (const user of usersData) {
   381→      // Check for ID conflicts
