   403→      const existingByEmail = await db.user.findUnique({
   404→        where: { email: userEmail },
   405→      });
   406→
   407→      if (existingByEmail) {
   408→        conflicts.push({
   409→          type: "user",
   410→          action: "create",
   411→          existingId: existingByEmail.id,
   412→          existingData: existingByEmail,
   413→          newData: user,
   414→          conflictFields: ["email"],
   415→          severity: "high",
   416→          description: `User with email ${userEmail} already exists`,
   417→        });
   418→      }
   419→    }
   420→
   421→    return conflicts;
