   423→
   424→  private async detectRelationshipConflicts(
   425→    relationshipsData: Record<string, unknown>[]
   426→  ): Promise<Conflict[]> {
   427→    const conflicts: Conflict[] = [];
   428→
   429→    for (const relationship of relationshipsData) {
   430→      // Check for ID conflicts
   431→      const relationshipId = String(relationship.id || "");
   432→      const existingById = await db.relationship.findUnique({
   433→        where: { id: relationshipId },
   434→      });
   435→
   436→      if (existingById) {
   437→        conflicts.push({
   438→          type: "relationship",
   439→          action: "update",
   440→          existingId: existingById.id,
   441→          existingData: existingById,
   442→          newData: relationship,
   443→          conflictFields: this.getChangedFields(existingById, relationship),
   444→          severity: "medium",
   445→          description: `Relationship with ID ${relationshipId} already exists`,
   446→        });
   447→        continue;
   448→      }
   449→
   450→      // Check for duplicate relationships
   451→      const relPersonId = String(relationship.personId || "");
   452→      const relRelatedPersonId = String(relationship.relatedPersonId || "");
   453→      const relTypeStr = String(relationship.type || "PARENT");
   454→      const validTypes = ["PARENT", "CHILD", "SPOUSE", "SIBLING"];
   455→      const relType = validTypes.includes(relTypeStr) ? relTypeStr : "PARENT";
   456→      const existingRelationship = await db.relationship.findFirst({
   457→        where: {
   458→          personId: relPersonId,
   459→          relatedPersonId: relRelatedPersonId,
   460→          type: relType as "PARENT" | "CHILD" | "SPOUSE" | "SIBLING",
   461→        },
   462→      });
   463→
   464→      if (existingRelationship) {
   465→        conflicts.push({
   466→          type: "relationship",
   467→          action: "create",
   468→          existingId: existingRelationship.id,
   469→          existingData: existingRelationship,
   470→          newData: relationship,
   471→          conflictFields: ["personId", "relatedPersonId", "type"],
   472→          severity: "medium",
   473→          description: `Duplicate relationship between ${relationship.personId} and ${relationship.relatedPersonId}`,
   474→        });
   475→      }
   476→    }
   477→
   478→    return conflicts;
   479→  }
   480→
   481→  private getChangedFields(
   482→    existing: Record<string, unknown>,
   483→    incoming: Record<string, unknown>
   484→  ): string[] {
   485→    const changedFields: string[] = [];
   486→
   487→    for (const key in incoming) {
   488→      if (existing[key] !== incoming[key]) {
   489→        changedFields.push(key);
   490→      }
   491→    }
   492→
   493→    return changedFields;
   494→  }
   495→
   496→  private createValidationResult(
   497→    isValid: boolean,
   498→    conflicts: Conflict[],
   499→    errors: string[],
   500→    warnings: string[]
   501→  ): ValidationResult {
   502→    const conflictsByType: Record<string, number> = {};
   503→    const conflictsBySeverity: Record<string, number> = {};
   504→
   505→    for (const conflict of conflicts) {
   506→      conflictsByType[conflict.type] =
   507→        (conflictsByType[conflict.type] || 0) + 1;
   508→      conflictsBySeverity[conflict.severity] =
   509→        (conflictsBySeverity[conflict.severity] || 0) + 1;
   510→    }
   511→
   512→    return {
   513→      isValid,
   514→      metadata: this.metadata!,
   515→      conflicts,
   516→      statistics: {
   517→        totalConflicts: conflicts.length,
   518→        conflictsByType,
   519→        conflictsBySeverity,
   520→      },
   521→      errors,
   522→      warnings,
   523→    };
   524→  }
   525→
   526→  getExtractedFiles(): Map<string, any> {
   527→    return this.extractedFiles;
   528→  }
   529→
   530→  getMetadata(): BackupMetadata | null {
   531→    return this.metadata;
   532→  }
   533→}
